    "content": "Bir Disiplin Olarak Dinler Tarihi, Karşılaştırmalı Dinler Tarihi, Karşılaştırma Metodu, Din Fenomenlerinin Karşılaştırılmasında Karşılaşılan Problemler ve Çözüm Önerileri, Dinlerdeki Bazı Fenomenlerin Karşılaştırılması: Din Kurucuları, Kutsal Kitap, Mabet, Kutsal Zamanlar, Hac, Oruç. Kefaret, Kurban, Kıble gibi.",
    "methods": "Anlatım, Soru-Yanıt",
    "resources": "Kaynaklar: Ahmet Güç, Dinlerde Mabed ve İbadet; Ahmet Güç, Çeşitli Dinlerde ve İslam'da Kurban; Albrecht Noth, Müslümanlıkta ve Hıristiyanlıkta Kutsal Savaş ve Mücadele; A. Küçük-G. Tümer, Dinler Tarihi; Mariasusai Dhavamony, Çev. Fuat Aydın, Dinlerde Tanrı Anlayışı; Dia, İlgili Maddeler; Ali Erbaş, Melekler Alemi.; Ders Notları: Karşılaştırmalı Dinler Tarihi",
