    "content": "Dinler tarihinin gelişim süreci; dinler tarihinin kavramları, tarihsel kaynaklar, karşılaştırmalı yöntem, dinî geleneklerin oluşumu, metin ve ritüel çözümlemesi, dinler arası etkileşim, yerel inanışlar, güncel dinler tarihi tartışmaları boyutlarıyla ele alınır.",
