    "programName": "Felsefe ve Din Bilimleri",
    "language": "Türkçe",
    "level": "Tezli Yüksek Lisans",
    "teachingMode": "Yüz Yüze",
    "theory": 3,
    "practice": 0,
    "credit": 3,
    "ects": 6,
    "prerequisites": "Yok",
    "instructor": "Dr. Öğr. Üyesi Eyyup Serkan ÖNCEL esoncel@osmaniywe.edu.tr",
    "purpose": "Bu ders, din öğretiminde temel kavramları ve öğrenme ilkelerini tanıtarak öğrencilerin öğretim sürecine yönelik kuramsal ve uygulamalı farkındalık kazanmalarını amaçlar.",
    "content": "Din öğretiminde temel kavramlar, öğrenme kuramları ve ilkeleri, öğrenmeyi etkileyen bireysel farklar, motivasyon, anlamlı ve kalıcı öğrenme, öğretim sürecinde öğrenme ilkelerinin uygulanması.",
    "methods": "Anlatım, tartışma, örnek olay analizi, kavram haritası, beyin fırtınası ve seminer sunumları.",
    "resources": "Kaynaklar: Hökelekli, H. (2011). Din Psikolojisi. Ankara: Diyanet Vakfı Yayınları.Selçuk, M. (2015). Din Öğretimi Kuramları. Ankara: Nobel YayıncılıkDemir, Z. (2018). Din Eğitimi ve Öğretiminde Yeni Yaklaşımlar. İstanbul: DEM Yayınları.; Ders Notları: Kaya, M. (2019). Din Öğretimi ve Öğrenme Psikolojisi. Nobel.Selçuk, M. (2018). Din Eğitimi Bilimine Giriş. Grafiker.Aydın, M. Ş. (2017). Eğitim Psikolojisi. Pegem Akademi.",
    "sdgs": [
      "4",
      "10",
      "16"
    ],
    "outcomes": [
      "Din öğretiminde kavramlar ve öğrenme ilkeleri kapsamındaki temel ve ileri yaklaşımları analiz eder.",
      "Din eğitimi alanındaki uygulamaları karşılaştırır.",
      "Din öğretiminde kavramlar ve öğrenme ilkeleri için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Din öğretiminde kavramlar ve öğrenme ilkeleri faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Din öğretiminde kavramlar ve öğrenme ilkeleri bulgularını etik ve bilimsel ölçütlerle yorumlar."
    ],
    "weeklyTopics": [
      "Din öğretimi ve öğrenme ilkelerine giriş",
      "Din öğretiminde kavramların önemi",
      "Öğrenme kuramlarına genel bakış",
      "Davranışçı öğrenme kuramı ve din öğretimi",
      "Bilişsel öğrenme kuramı ve din öğretimi",
      "Yapılandırmacı yaklaşım ve din öğretimi",
      "Öğrenme ilkeleri ve din öğretiminde uygulamaları",
      "Bilişsel, duyuşsal ve psikomotor öğrenme alanları",
      "Öğrenmede motivasyon ve ilgililik",
      "Öğrenmeyi etkileyen bireysel farklar",
      "Öğrenme ortamı ve öğrenme iklimi",
      "Anlamlı ve kalıcı öğrenme",
      "Öğrenme ilkelerinin öğretim sürecine yansıtılması",
      "Genel değerlendirme ve yansıtma",
      "Din öğretiminde kavramlar ve öğrenme ilkeleri: kapsam ve temel kavramlar"
    ],
