    "purpose": "Bu dersin amacı, dinler tarihinin temel kavramlarını, terimlerini ve kuramsal çerçevesini öğrencilere tanıtmaktır. Öğrencilerin farklı dini gelenekleri karşılaştırmalı olarak anlamalarına ve tarihsel süreçte din olgusunu analiz etmelerine katkı sağlamak hedeflenir. Ders sonunda öğrenciler: Din, inanç, mit, ritüel, kutsal, tabu, totem, vahiy gibi temel kavramları tanımlar.",
