    "department": "Felsefe ve Din Bilimleri ABD",
    "programName": "Felsefe ve Din Bilimleri",
    "language": "Türkçe",
    "level": "Tezli Yüksek Lisans",
    "teachingMode": "Yüz Yüze",
    "theory": 3,
    "practice": 0,
    "credit": 3,
    "ects": 6,
    "prerequisites": "Yok",
    "instructor": "Dr. Öğr. Üyesi İbrahim YILDIRIM https://akbis.osmaniye.edu.tr/@ibrahimyildirim ibrahimyildirim@osmaniye.edu.tr",
    "purpose": "Gelişimle ilgili temel konular, araştırma yöntem ve teknikleri, gelişim teorileri, gelişim dönemleri, gelişim dönemlerinde ortaya çıkan bedensel, bilişsel, kişilik ve ahlak gelişimi, dini duygu ve düşüncelerin gelişmesi ile ilgili genel yaklaşımlar, dini gelişim teorileri, dini his, dini şuur vd. kavram, ilke ve becerilerin kazandırılması amaçlanmaktadır.",
    "content": "Bu ders, bireyin yaşam boyu gelişimini psikolojik açıdan ele alır ve bu gelişimin dini inanç, duygu ve davranış üzerindeki etkilerini inceler. Temel gelişim ilkeleri, bilişsel, ahlaki ve kişilik gelişimi kuramları ile dini gelişim teorileri (Piaget, Erikson, Kohlberg, Fowler, Goldman, Jung vb.) açıklanır. Çocukluk, ergenlik, yetişkinlik ve yaşlılık dönemlerinde dini gelişimin karakteristikleri tartışılır.",
    "methods": "Anlatım, Soru-Cevap, Beyin Fırtınası, Tartışma, Örnek Olay",
    "resources": "Kaynaklar: Faruk Karaca, Dinî Gelişim Psikolojisi, Eser Ofset Matbaacılık, Trabzon, 2016.Ergin, Hatice ve Köseoğlu, S. Armağan. Gelişim Psikolojisi, Nobel Akademik Yay. Ankara, 2017.Faruk Karaca, Dinî Gelişim Teorileri, Kitapyurdu Doğrudan Yay., İstanbul: 2023Fatma Baynal, Ernest Harms’ın Dini Gelişim Teorisinin Tanrı Tasavvuru Kuramları Bağlamında İncelenmesi, İlahiyat Tetkikleri Dergisi, 61/1 (Haziran 2024), 122-140 Gürses, İbrahim ve Kılavuz, M. Akif. Kuşakların Ahlâkî Değerleri Birlikte Öğrenmesi: Kohlberg’in Ahlâkî Gelişim Kuramı Açısından Bir Değerlendirme, Uüifd, Cilt 25, Sayı 1, 2016; Ders Notları: Faruk Karaca, Dinî Gelişim Psikolojisi, Eser Ofset Matbaacılık, Trabzon, 2016.Hatice Ergin Ve S. Armağan Köseoğlu, Gelişim Psikolojisi, Nobel Akademik Yay. Ankara, 2017.",
    "sdgs": [
      "4",
      "10",
      "16"
    ],
    "outcomes": [
      "Gelişim dönemleri ve din kapsamındaki temel ve ileri yaklaşımları analiz eder.",
      "Felsefe ve din bilimleri alanındaki uygulamaları karşılaştırır.",
      "Gelişim dönemleri ve din için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Gelişim dönemleri ve din faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Gelişim dönemleri ve din bulgularını etik ve bilimsel ölçütlerle yorumlar."
    ],
    "weeklyTopics": [
      "Gelişim Psikolojisinin İçeriği ve Temel Kavramlar",
      "Gelişim İlkeleri ve Gelişim Görevleri Kuramı",
      "Dinî Gelişimi Etkileyen Bireysel, Sosyal, Doğal Faktörler; Duygusal ve Sosyal Gelişim",
      "Piaget’nin Bilişsel Gelişim Kuramı, Elkind ve Arayış Teorisi",
      "Harms ve Dinî Düşüncenin Gelişimi Kuramı",
      "Freud’un Kişilik Gelişimi Kuramı",
      "Erikson’un Psikososyal Gelişim Kuramı",
      "Kohlberg’in Ahlak Gelişim Kuramı",
      "Jung ve Bireyleşme Teorisi",
      "Fowler ve İnanç Gelişimi Teorisi",
      "Goldman ve Dinî Düşünce Gelişimi Kuramı",
      "Çocukluk Dönemi Dini Gelişim, Ergenlik Dönemi Dini Gelişim",
      "Yetişkinlik Dönemi Dini Gelişim, Yaşlılık Dönemi Dini Gelişim",
      "Gelişim dönemleri ve din: kapsam ve temel kavramlar",
      "Temel kavram ve kuramlar"
    ],
