    "content": "Ders kapsamında; Freud’un din eleştirisi, Jung’un kolektif bilinçdışı ve arketipler kuramı, Adler’in bireysel psikolojisi, Fromm’un hümanist din yaklaşımı, Nesne İlişkileri kuramının Tanrı tasavvuru üzerindeki etkisi ve Otto Rank ile Winnicott’un dinsel sembolizme dair teorileri ele alınmaktadır.",
