    "ects": 6,
    "prerequisites": "Yok",
    "instructor": "Doç. Dr. beyazıt yaşar seyhan beyazit.seyhan1@gmail.com",
    "purpose": "Dindarlığın insan yaşamı üzerindeki etkilerini anlamak",
    "content": "Dini gelişim dindarlık vb. gibi konuların ana temel kavramları anlamış ve bilmiş olmayı içerir",
    "methods": "Anlatım soru cevap ve benzeri eğitim öğretim teknikleri",
