    "content": "Sosyolojiye giriş mahiyetinde toplum, sosyal olay, olgu, kurum, yapı ve benzeri temel kavramlar ile sosyolojinin ve din sosyolojisinin yöntemi ve tarihsel sürecine dahil bilgiler içerir.",
