    "purpose": "Ekonomik faaliyetin insan hayatındaki yeri ve etkileri. İbn Haldun'da din-ekonomi ilişkisinin incelenmesi. Sosyal ekonomi ve sosyal siyasetle ilgili görüşlerden yararlanılması. İslam ekonomik düşüncesi tarihinin incelenmesi. Zihniyet din ilişkisi bağlamında toplumsal değişimin incelenmesi.",
    "content": "Modern kapitalizmin doğasında dinin rolü ve kapitalizmin ruhu ile protestan ahlakı arasındaki ilişkiler. Din ve ekonomi arasındaki ilişkinin sosyolojik perspektiften ele alınması. Din-ekonomi ilişkilerine güncel yaklaşımlar.",
    "methods": "Anlatım, Tartışma, Soru-cevap.",
    "resources": "Kaynaklar: Bodur, Hüsnü Ezber. Modern Kapitalizmin Doğmasında Dinin Rolü, Atatürk Üniversitesi İlahiyat Fakültesi Dergisi, 9, Erzurum 1990, ss. 80-95.Maxim Rodinson, İslam ve KapitalizmÜlgener, Sabri Fehmi, Zihniyet ve Din İslam Tasavvuf ve Çözülme Devri.Ahmet Güner Sayar, Bir İktisatçının Entelektüel Portresi: Sabri F. Ülgener.; Ders Notları: Bodur, Hüsnü Ezber. Modern Kapitalizmin Doğmasında Dinin Rolü, Atatürk Üniversitesi İlahiyat Fakültesi Dergisi, 9, Erzurum 1990, ss. 80-95.; Dökümanlar: Bodur, Hüsnü Ezber. Modern Kapitalizmin Doğmasında Dinin Rolü, Atatürk Üniversitesi İlahiyat Fakültesi Dergisi, 9, Erzurum 1990, ss. 80-95.",
